def apply(inputs, premises):
    question = str(inputs.get("question", "")).casefold()
    records = premises.get("records", []) if isinstance(premises, dict) else []
    employee_query = "employee" in question and "third-part" not in question
    third_query = "third-part" in question or "consultant" in question or "professional advisor" in question or "professional adviser" in question
    if not employee_query and not third_query:
        return {"handled": False, "answer": "NotMentioned", "used_records": []}
    employee_permission = -1
    external_permission = -1
    internal_permission = -1
    restricted_permission = -1
    anaphoric_employee = -1
    broad_prohibition = -1
    nonspecific_rule = -1
    external_symbols = ["contractor", "consultant", "agent", "legal_advisor", "financial_advisor", "professional_advisor", "accountant", "lender"]
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        values = record.get("values", {})
        if not isinstance(values, dict):
            continue
        relation = str(values.get("relation", "")).casefold()
        roles = str(values.get("recipient_classes", "")).casefold()
        if relation == "permit_disclosure":
            if "employee" in roles and employee_permission < 0:
                employee_permission = index
            if external_permission < 0 and any(symbol in roles for symbol in external_symbols):
                external_permission = index
        elif relation == "restricted_access_permission":
            if restricted_permission < 0:
                restricted_permission = index
            if external_permission < 0 and any(symbol in roles for symbol in external_symbols):
                external_permission = index
        elif relation == "permit_internal_share":
            if internal_permission < 0:
                internal_permission = index
        elif relation == "anaphoric_recipient_enumeration":
            if "employee" in roles and anaphoric_employee < 0:
                anaphoric_employee = index
        elif relation == "prohibit_disclosure":
            scope = str(values.get("recipient_scope", "")).casefold()
            if scope == "broad_third_party" and broad_prohibition < 0:
                broad_prohibition = index
        elif relation == "nonspecific_purpose_exception_rule":
            if nonspecific_rule < 0:
                nonspecific_rule = index
    if employee_query:
        if employee_permission >= 0:
            return {"handled": True, "answer": "Entailment", "used_records": [employee_permission]}
        if internal_permission >= 0:
            return {"handled": True, "answer": "Entailment", "used_records": [internal_permission]}
        if restricted_permission >= 0 and anaphoric_employee >= 0:
            return {"handled": True, "answer": "Entailment", "used_records": [restricted_permission, anaphoric_employee]}
        if nonspecific_rule >= 0:
            return {"handled": True, "answer": "NotMentioned", "used_records": [nonspecific_rule]}
        return {"handled": False, "answer": "NotMentioned", "used_records": []}
    if external_permission >= 0:
        return {"handled": True, "answer": "Entailment", "used_records": [external_permission]}
    if broad_prohibition >= 0:
        return {"handled": True, "answer": "Contradiction", "used_records": [broad_prohibition]}
    if nonspecific_rule >= 0:
        return {"handled": True, "answer": "NotMentioned", "used_records": [nonspecific_rule]}
    return {"handled": False, "answer": "NotMentioned", "used_records": []}
